#ifndef ES2_VSHELL_PROBES_H
#define ES2_VSHELL_PROBES_H
/* Entry probes in VSHELL.EXE (the code of the VSHELL function
 * map; docs/reference-game/vshell_map.md). The probe engine of DBSIM's map
 * (entry_probe_engine.h) on the known function starts of the reference
 * VER95\VSHELL.EXE (vshell_probe_inventory.h, generated by
 * scripts/probe_instruction_inventory.py --module vshell): every start's
 * first byte becomes INT3, the handler counts and emulates the original
 * instruction. Counters per function go to a JSON report at exit.
 *
 * Off unless the INI named by ES2_LIVE_COVERAGE_CONFIG has [vshell_probes]
 * enabled=1 and the process is VSHELL.EXE. Without the variable the attach
 * path stops after GetModuleFileNameW and GetEnvironmentVariableW; nothing
 * of the proxy or of VSHELL changes. The DBSIM paths (entry_probes.h,
 * live_coverage.h, vol_probes.h) are not touched: they return for any
 * process but DBSIM.EXE, and this header returns for any process but
 * VSHELL.EXE, so the one engine instance is never shared.
 *
 * Arming, in two steps:
 * 1. DLL_PROCESS_ATTACH (install_vshell_probes, loader lock: kernel32
 *    memory calls, one GetPrivateProfileIntW as vol_probes.h does): the
 *    loaded image is checked (PE header: base 0x400000, SizeOfImage
 *    0x1ea000) and VSHELL's import slot of cw3220 __startup is pointed at
 *    vsp_startup_entry. VSHELL's entry 0x401000 reaches __startup through
 *    the thunk 0x46b9be (jmp [0x5de2ec]) after its own set-up.
 * 2. vsp_startup_entry (outside the loader lock, every DLL initialised):
 *    puts the original slot value back, then vsp_start reads the INI,
 *    checks the module file's SHA-256 (1534aa8f...a16e), registers the
 *    report at cw3220 _atexit (normal end: WinMain returns, the RTL runs
 *    the atexit list) and takes VSHELL's __exit import slot (assertion
 *    ends, vshell_process.md section 9), validates and installs the probes
 *    and writes a first report (reason "startup"). Then it jumps to the
 *    original __startup with every register and flag unchanged.
 * The entry 0x401000, its callee 0x46b68d and the import thunk 0x46baae run
 * before step 2: their first (start-up) entries are never counted.
 *
 * INI keys ([vshell_probes]): enabled=0|1, report=<path of the JSON>,
 * mode=count|saturate (default count), saturate_after=<n> (default 1),
 * ("{pid}" is replaced by the process id; a report file that already exists
 * refuses the arming), entries=all (default: every row of vshell_probe_function_starts) or a
 * comma list of hex VAs (each a known start or a push row of the first
 * table). With [compat] mission_map_lifetime=1 in the proxy's
 * es2-oracle.ini the byte ranges the mission-map guard checks or patches
 * are left without probes ("all" drops them, a list naming one is refused).
 *
 * Report (schema 1): module, module_sha256, mode, saturate_after, pid,
 * install/first/other thread, error (the engine's ep_error), complete
 * (probes restored at exit), reason (startup, exit, immediate_exit,
 * install_failed), sites, then one row per site: va, kind (0 = push r32,
 * else the EP_* index of entry_probe_engine.h), count, saturated. */
#include <windows.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <wchar.h>
#include "entry_probe_engine.h"
#include "vshell_probe_inventory.h"
#include "sha256.h"
#include "hook/hook.h"

#define VSP_BASE 0x00400000u
#define VSP_IMAGE_SIZE 0x001ea000u
#define VSP_FILE_SIZE 566304u
#define VSP_MODULE_HASH "1534aa8f732bdecd826484d893ad58b8a5e6ebd4d25ab3158a2469b8f69ba16e"
#define VSP_STARTS (sizeof(vshell_probe_function_starts) / sizeof(vshell_probe_function_starts[0]))
#define VSP_MAX_EXCLUDED 8u
enum { VSP_OFF, VSP_PENDING, VSP_ARMED, VSP_REFUSED, VSP_DONE };

static volatile LONG vsp_state;
static ep_site *vsp_sites;
static unsigned vsp_count, vsp_mode = LC_COUNT;
static LONG64 vsp_limit = 1;
static DWORD vsp_install_thread;
static const char *vsp_reason = "startup";
static BOOL vsp_complete;
static WCHAR vsp_ini[MAX_PATH], vsp_guard_ini[MAX_PATH], vsp_path[MAX_PATH], vsp_temp[MAX_PATH];
static lc_range vsp_excluded[VSP_MAX_EXCLUDED];
static unsigned vsp_nexcluded;
/* Import slots of the loaded VSHELL image and their original values. */
static DWORD *vsp_startup_slot, *vsp_exit_slot;
static DWORD vsp_exit_original;
__attribute__((used)) static DWORD vsp_startup_original;
static volatile LONG vsp_arm_calls;

/* --- inventory lookups ------------------------------------------------- */
static BYTE vsp_opcode(uint32_t va) {
    size_t low = 0, high = sizeof(vshell_probe_instructions) / sizeof(vshell_probe_instructions[0]);
    while (low < high) {
        size_t mid = low + (high - low) / 2; uint32_t value = vshell_probe_instructions[mid].va;
        if (value == va) return vshell_probe_instructions[mid].opcode;
        if (value < va) low = mid + 1; else high = mid;
    }
    return 0;
}
static unsigned vsp_kind_of(uint32_t va) {
    size_t low = 0, high = sizeof(vshell_probe_entry_kinds) / sizeof(vshell_probe_entry_kinds[0]);
    while (low < high) {
        size_t mid = low + (high - low) / 2; uint32_t value = vshell_probe_entry_kinds[mid].va;
        if (value == va) return vshell_probe_entry_kinds[mid].kind;
        if (value < va) low = mid + 1; else high = mid;
    }
    return EP_KINDS;
}
/* Site for a VA: a push row (EP_PUSH with its opcode) or a row of the kind table. */
static BOOL vsp_site_for(ep_site *s, uint32_t va) {
    BYTE opcode = vsp_opcode(va);
    unsigned kind = opcode ? EP_PUSH : vsp_kind_of(va);
    if (kind == EP_KINDS) return FALSE;
    memset(s, 0, sizeof(*s));
    s->patch.address = va; s->patch.length = 1; s->patch.saved[0] = opcode; s->kind = kind; s->receiver = EP_NONE;
    return TRUE;
}
static BOOL vsp_excluded_site(uint32_t va, unsigned kind) {
    for (unsigned j = 0; j < vsp_nexcluded; ++j)
        if (va < vsp_excluded[j].start + vsp_excluded[j].size && vsp_excluded[j].start < va + ep_kind_length[kind]) return TRUE;
    return FALSE;
}
static int vsp_compare(const void *a, const void *b) {
    uintptr_t x = ((const ep_site *)a)->patch.address, y = ((const ep_site *)b)->patch.address;
    return x < y ? -1 : x > y;
}

/* --- configuration ----------------------------------------------------- */
static BOOL vsp_get(const WCHAR *ini, const WCHAR *key, const WCHAR *fallback, WCHAR *out, DWORD size) {
    return GetPrivateProfileStringW(L"vshell_probes", key, fallback, out, size, ini) < size - 1;
}
static BOOL vsp_decimal(const WCHAR *ini, const WCHAR *key, const WCHAR *fallback, DWORD *out) {
    WCHAR text[24]; if (!vsp_get(ini, key, fallback, text, 24) || !*text) return FALSE;
    uint32_t n = 0;
    for (unsigned i = 0; text[i]; ++i) {
        unsigned d = text[i] - L'0';
        if (d > 9 || n > (UINT32_MAX - d) / 10) return FALSE;
        n = n * 10 + d;
    }
    *out = n; return TRUE;
}
/* Sites from "all" or a list of hex VAs into `sites` (capacity VSP_STARTS),
 * sorted by address; FALSE for an unknown, repeated or excluded VA. */
static BOOL vsp_select(const WCHAR *text, ep_site *sites, unsigned *count) {
    unsigned n = 0;
    if (!wcscmp(text, L"all")) {
        for (unsigned i = 0; i < VSP_STARTS; ++i) {
            ep_site s;
            if (!vsp_site_for(&s, vshell_probe_function_starts[i])) return FALSE;
            if (!vsp_excluded_site(vshell_probe_function_starts[i], s.kind)) sites[n++] = s;
        }
        *count = n; return n != 0;
    }
    const WCHAR *p = text;
    while (*p) {
        if (n == VSP_STARTS) return FALSE;
        while (*p == L' ' || *p == L'\t') ++p;
        if (p[0] == L'0' && (p[1] == L'x' || p[1] == L'X')) p += 2;
        uint32_t va = 0; unsigned digits = 0;
        for (;;) {
            unsigned d = *p >= L'0' && *p <= L'9' ? *p - L'0' : *p >= L'a' && *p <= L'f' ? *p - L'a' + 10 :
                         *p >= L'A' && *p <= L'F' ? *p - L'A' + 10 : 16;
            if (d == 16) break;
            if (++digits > 8) return FALSE;
            va = va * 16 + d; ++p;
        }
        while (*p == L' ' || *p == L'\t') ++p;
        if (!digits || (*p && *p != L',') || !vsp_site_for(&sites[n], va) || vsp_excluded_site(va, sites[n].kind)) return FALSE;
        for (unsigned i = 0; i < n; ++i) if (sites[i].patch.address == va) return FALSE;
        ++n;
        if (!*p) break;
        if (!*++p) return FALSE;
    }
    if (!n) return FALSE;
    qsort(sites, n, sizeof(sites[0]), vsp_compare);
    *count = n; return TRUE;
}
/* 0 off, 1 on, -1 malformed. Fills the sites (vsp_sites must hold VSP_STARTS). */
static int vsp_configuration(const WCHAR *ini) {
    WCHAR enabled[8], mode[24], entries[8192]; DWORD limit;
    if (!vsp_get(ini, L"enabled", L"0", enabled, 8)) return -1;
    if (!wcscmp(enabled, L"0")) return 0;
    if (wcscmp(enabled, L"1") || !vsp_get(ini, L"mode", L"count", mode, 24)) return -1;
    if (!wcscmp(mode, L"count")) vsp_mode = LC_COUNT; else if (!wcscmp(mode, L"saturate")) vsp_mode = LC_SATURATE; else return -1;
    if (!vsp_decimal(ini, L"saturate_after", L"1", &limit) || !limit ||
        !vsp_get(ini, L"entries", L"all", entries, 8192) || !vsp_select(entries, vsp_sites, &vsp_count) ||
        !vsp_get(ini, L"report", L"", vsp_path, MAX_PATH) || !*vsp_path || wcslen(vsp_path) > MAX_PATH - 32) return -1;
    vsp_limit = limit; return 1;
}
/* "{pid}" in the report path becomes the process id (one report per VSHELL
 * process of a session: VSHELL ends at every mission start and returns). */
static BOOL vsp_expand_pid(WCHAR *path, DWORD pid) {
    WCHAR *at = wcsstr(path, L"{pid}"), tail[MAX_PATH];
    if (!at) return TRUE;
    wcscpy(tail, at + 5);
    int n = swprintf(at, MAX_PATH - (at - path), L"%lu%ls", (unsigned long)pid, tail);
    return n > 0 && !wcsstr(path, L"{pid}") && wcslen(path) <= MAX_PATH - 32;
}

/* --- engine over more than EP_MAX_ENTRIES sites ------------------------ */
/* ep_install validates at most EP_MAX_ENTRIES sites; the handler itself has
 * no limit. The sites are validated in chunks by ep_validate, overlaps
 * between chunks by the sorted order, then patched as ep_install does. */
static BOOL vsp_install_sites(ep_site *sites, unsigned count, BYTE *image, size_t size,
                              const lc_range *excluded, unsigned nexcluded, unsigned mode, LONG64 limit) {
    if (ep_active || ep_handler || !count || mode > LC_COUNT || limit < 1) return FALSE;
    for (unsigned i = 0; i < count; i += EP_MAX_ENTRIES) {
        unsigned n = count - i < EP_MAX_ENTRIES ? count - i : EP_MAX_ENTRIES;
        if (!ep_validate(sites + i, n, image, size, excluded, nexcluded)) return FALSE;
    }
    for (unsigned i = 1; i < count; ++i)
        if (sites[i].patch.address < sites[i - 1].patch.address + sites[i - 1].size) return FALSE;
    ep_sites = sites; ep_count = count; ep_mode = mode; ep_limit = limit;
    ep_error = ep_first_thread = ep_other_thread = 0;
    for (unsigned i = 0; i < count; ++i) {
        sites[i].count = sites[i].overflow = 0; memset(sites[i].receivers, 0, sizeof(sites[i].receivers));
        sites[i].patch.installed = sites[i].patch.restored = 0;
    }
    ep_handler = AddVectoredExceptionHandler(1, ep_exception); if (!ep_handler) return FALSE;
    ep_active = 1;
    for (unsigned i = 0; i < count; ++i) {
        lc_site *p = &sites[i].patch; DWORD old, ignored;
        if (!lc_protect((void *)p->address, 1, PAGE_EXECUTE_READWRITE, &old)) { ep_error = 3; ep_uninstall(); return FALSE; }
        p->protection = old; p->installed = 1; *(BYTE *)p->address = 0xcc;
        BOOL flushed = lc_flush(GetCurrentProcess(), (void *)p->address, 1);
        BOOL protected = lc_protect((void *)p->address, 1, old, &ignored);
        if (!flushed || !protected) { ep_error = 4; ep_uninstall(); return FALSE; }
    }
    return TRUE;
}

/* --- report ------------------------------------------------------------ */
static BOOL vsp_write(HANDLE f, const char *text, int n) {
    DWORD written = 0; return n >= 0 && WriteFile(f, text, (DWORD)n, &written, NULL) && written == (DWORD)n;
}
static BOOL vsp_report(void) {
    HANDLE f = CreateFileW(vsp_temp, GENERIC_WRITE, 0, NULL, CREATE_NEW, FILE_ATTRIBUTE_NORMAL, NULL);
    if (f == INVALID_HANDLE_VALUE) { ep_error = 7; return FALSE; }
    char text[512];
    int n = snprintf(text, sizeof(text), "{\"schema\":1,\"module\":\"VSHELL.EXE\",\"module_sha256\":\"%s\",\"mode\":\"%s\",\"saturate_after\":%llu,"
        "\"pid\":%lu,\"install_thread\":%lu,\"first_thread\":%lu,\"other_thread\":%lu,\"error\":%ld,\"complete\":%s,\"reason\":\"%s\",\"sites\":%u,\"entries\":[",
        VSP_MODULE_HASH, vsp_mode == LC_COUNT ? "count" : "saturate", (unsigned long long)vsp_limit, (unsigned long)GetCurrentProcessId(),
        (unsigned long)vsp_install_thread, (unsigned long)ep_first_thread, (unsigned long)ep_other_thread, (long)ep_error,
        vsp_complete ? "true" : "false", vsp_reason, vsp_count);
    BOOL ok = vsp_write(f, text, n);
    for (unsigned i = 0; ok && i < vsp_count; ++i) {
        const ep_site *s = &vsp_sites[i]; LONG64 count = lc_read64((volatile LONG64 *)&s->count);
        n = snprintf(text, sizeof(text), "%s\n{\"va\":\"0x%08lx\",\"kind\":%u,\"count\":%llu,\"saturated\":%s}", i ? "," : "",
                     (unsigned long)s->patch.address, s->kind, (unsigned long long)count,
                     vsp_mode == LC_SATURATE && count >= vsp_limit ? "true" : "false");
        ok = vsp_write(f, text, n);
    }
    ok = ok && vsp_write(f, "]}\n", 3);
    if (ok) ok = FlushFileBuffers(f);
    if (!CloseHandle(f)) ok = FALSE;
    if (ok) ok = MoveFileExW(vsp_temp, vsp_path, MOVEFILE_REPLACE_EXISTING | MOVEFILE_WRITE_THROUGH);
    if (!ok) { DeleteFileW(vsp_temp); ep_error = 7; }
    return ok;
}

/* --- import slots and exit --------------------------------------------- */
/* VSHELL's import slot of `symbol` from cw3220.DLL, found by name in the
 * loaded image's import table (bounded to `size`). */
static DWORD *vsp_import_slot(BYTE *image, size_t size, const char *symbol) {
    if (size < 4096 || !lc_readable((uintptr_t)image, 4096) || image[0] != 'M' || image[1] != 'Z') return NULL;
    DWORD pe = lc_u32(image + 0x3c);
    if (pe > 4096 - 248 || memcmp(image + pe, "PE\0\0", 4) || lc_u32(image + pe + 116) < 2) return NULL;
    DWORD rva = lc_u32(image + pe + 128), extent = lc_u32(image + pe + 132);
    if (rva >= size || extent > size - rva || !lc_readable((uintptr_t)image + rva, extent)) return NULL;
    size_t length = strlen(symbol) + 1;
    for (DWORD i = 0; i + 1 <= extent / 20; ++i) {
        const BYTE *d = image + rva + 20 * i; DWORD name = lc_u32(d + 12);
        if (!name) break;
        if (name > size - 11 || !lc_readable((uintptr_t)image + name, 11)) return NULL;
        if (_strnicmp((const char *)image + name, "cw3220.DLL", 11)) continue;
        DWORD names = lc_u32(d), slots = lc_u32(d + 16);
        if (!names || names >= size || slots >= size) return NULL;
        for (DWORD j = 0; j < (size - names) / 4 && j < (size - slots) / 4; ++j) {
            if (!lc_readable((uintptr_t)image + names + 4 * j, 4) || !lc_readable((uintptr_t)image + slots + 4 * j, 4)) return NULL;
            DWORD entry = lc_u32(image + names + 4 * j);
            if (!entry) break;
            if (entry & 0x80000000u) continue;
            if (entry > size - length - 2 || !lc_readable((uintptr_t)image + entry, length + 2)) return NULL;
            if (!memcmp(image + entry + 2, symbol, length)) return (DWORD *)(image + slots + 4 * j);
        }
    }
    return NULL;
}
static BOOL vsp_swap(DWORD *slot, DWORD expected, DWORD value) {
    DWORD old, ignored;
    if (!VirtualProtect(slot, 4, PAGE_READWRITE, &old)) return FALSE;
    BOOL ok = (DWORD)InterlockedCompareExchange((LONG *)slot, (LONG)value, (LONG)expected) == expected;
    if (!VirtualProtect(slot, 4, old, &ignored)) ok = FALSE;
    return ok;
}
static void __cdecl vsp_exit(int code);
static BOOL vsp_restore_exit(void) {
    if (!vsp_exit_slot) return TRUE;
    BOOL ok = *vsp_exit_slot == vsp_exit_original ||
              vsp_swap(vsp_exit_slot, (DWORD)(uintptr_t)vsp_exit, vsp_exit_original);
    if (ok) vsp_exit_slot = NULL;
    return ok;
}
static void vsp_shutdown(const char *reason) {
    if (InterlockedCompareExchange(&vsp_state, VSP_DONE, VSP_ARMED) != VSP_ARMED) return;
    __attribute__((aligned(16))) BYTE fpu[512]; __asm__ volatile("fxsave %0" : "=m"(fpu));
    DWORD error = GetLastError();
    /* As entry_probes.h: restore only when no second thread entered a probe. */
    BOOL owned = !ep_other_thread && (!ep_first_thread || (DWORD)ep_first_thread == GetCurrentThreadId());
    if (!owned) ep_error = 6;
    BOOL restored = owned && ep_uninstall();
    if (!vsp_restore_exit()) { ep_error = 9; restored = FALSE; }
    vsp_complete = restored && !ep_error; vsp_reason = reason; vsp_report();
    SetLastError(error); __asm__ volatile("fxrstor %0" :: "m"(fpu));
}
static void __cdecl vsp_on_exit(void) { vsp_shutdown("exit"); }
static void (__cdecl *vsp_previous_exit)(int);
static void __cdecl vsp_exit(int code) { vsp_shutdown("immediate_exit"); vsp_previous_exit(code); }
/* Normal end through the RTL's atexit list, immediate end through __exit. */
static BOOL vsp_install_exit(DWORD *exit_slot, DWORD *atexit_slot) {
    if (!exit_slot || !atexit_slot) return FALSE;
    int (__cdecl *register_exit)(void (__cdecl *)(void)) = (void *)(uintptr_t)*atexit_slot;
    if (register_exit(vsp_on_exit)) return FALSE;
    vsp_exit_original = *exit_slot; vsp_previous_exit = (void *)(uintptr_t)vsp_exit_original;
    if (!vsp_swap(exit_slot, vsp_exit_original, (DWORD)(uintptr_t)vsp_exit)) return FALSE;
    vsp_exit_slot = exit_slot;
    return TRUE;
}

/* --- arming ------------------------------------------------------------ */
static BOOL vsp_reference_file(const WCHAR *path) {
    HANDLE f = CreateFileW(path, GENERIC_READ, FILE_SHARE_READ, NULL, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);
    if (f == INVALID_HANDLE_VALUE) return FALSE;
    sha256_ctx ctx; sha256_init(&ctx);
    BYTE buffer[16384]; DWORD got = 0, total = 0; BOOL ok = TRUE;
    while (ok) {
        if (!ReadFile(f, buffer, sizeof(buffer), &got, NULL)) ok = FALSE;
        else if (!got) break;
        else { total += got; sha256_update(&ctx, buffer, got); }
    }
    CloseHandle(f);
    char hex[65]; sha256_hex(&ctx, hex);
    return ok && total == VSP_FILE_SIZE && !strcmp(hex, VSP_MODULE_HASH);
}
/* The mission-map guard's checked and patched bytes, when it is configured. */
static void vsp_guard_exclusions(void) {
    vsp_nexcluded = 0;
#ifdef ES2_MISSION_MAP_GUARD_H
    if (!*vsp_guard_ini || !GetPrivateProfileIntW(L"compat", L"mission_map_lifetime", 0, vsp_guard_ini)) return;
    for (unsigned i = 0; i < sizeof(map_guard_signatures) / sizeof(map_guard_signatures[0]) && vsp_nexcluded < VSP_MAX_EXCLUDED; ++i)
        vsp_excluded[vsp_nexcluded++] = (lc_range){VSP_BASE + map_guard_signatures[i].rva, map_guard_signatures[i].size};
#endif
}
static void vsp_start(void) {
    /* log_event reads [video] log from config_path, which the proxy sets at
     * the first DirectDraw/MCI call; set the same path now (as rtl_arm does). */
    if (!config_path[0] && vsp_guard_ini[0]) wcscpy(config_path, vsp_guard_ini);
    BYTE *image = (BYTE *)GetModuleHandleW(NULL);
    WCHAR exe[MAX_PATH]; DWORD n = GetModuleFileNameW(NULL, exe, MAX_PATH);
    vsp_guard_exclusions();
    vsp_sites = VirtualAlloc(NULL, VSP_STARTS * sizeof(ep_site), MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    int configured = vsp_sites ? vsp_configuration(vsp_ini) : -1;
    if (configured <= 0) {
        InterlockedExchange(&vsp_state, configured ? VSP_REFUSED : VSP_OFF);
        log_event(configured ? "vshell_probes_config_refused" : "vshell_probes_disabled");
        return;
    }
    if (!vsp_expand_pid(vsp_path, GetCurrentProcessId())) {
        InterlockedExchange(&vsp_state, VSP_REFUSED); log_event("vshell_probes_config_refused"); return;
    }
    if (!n || n >= MAX_PATH || !vsp_reference_file(exe) || !es2_hook_image_valid(image, VSP_BASE, VSP_IMAGE_SIZE)) {
        InterlockedExchange(&vsp_state, VSP_REFUSED); log_event("vshell_probes_hash_refused"); return;
    }
    swprintf(vsp_temp, MAX_PATH, L"%ls.tmp.%lu", vsp_path, (unsigned long)GetCurrentProcessId());
    HANDLE reserve = GetFileAttributesW(vsp_temp) == INVALID_FILE_ATTRIBUTES ?
        CreateFileW(vsp_path, GENERIC_WRITE, FILE_SHARE_READ, NULL, CREATE_NEW, FILE_ATTRIBUTE_NORMAL, NULL) : INVALID_HANDLE_VALUE;
    if (reserve == INVALID_HANDLE_VALUE) { InterlockedExchange(&vsp_state, VSP_REFUSED); log_event("vshell_probes_report_refused"); return; }
    CloseHandle(reserve);
    vsp_install_thread = GetCurrentThreadId();
    if (!vsp_install_exit(vsp_import_slot(image, VSP_IMAGE_SIZE, "__exit"), vsp_import_slot(image, VSP_IMAGE_SIZE, "_atexit"))) {
        InterlockedExchange(&vsp_state, VSP_REFUSED); log_event("vshell_probes_exit_refused"); return;
    }
    if (!vsp_install_sites(vsp_sites, vsp_count, image, VSP_IMAGE_SIZE, vsp_excluded, vsp_nexcluded, vsp_mode, vsp_limit)) {
        if (!ep_error) ep_error = 1;
        vsp_reason = "install_failed"; vsp_restore_exit(); vsp_report();
        InterlockedExchange(&vsp_state, VSP_REFUSED); log_event("vshell_probes_sites_refused"); return;
    }
    InterlockedExchange(&vsp_state, VSP_ARMED);
    vsp_report(); log_event("vshell_probes_installed");
}
__attribute__((used)) static void __cdecl vsp_arm(void) {
    __attribute__((aligned(16))) BYTE fpu[512]; __asm__ volatile("fxsave %0" : "=m"(fpu));
    DWORD error = GetLastError();
    InterlockedIncrement(&vsp_arm_calls);
    if (vsp_startup_slot && vsp_swap(vsp_startup_slot, *vsp_startup_slot, vsp_startup_original)) vsp_startup_slot = NULL;
    if (InterlockedCompareExchange(&vsp_state, VSP_REFUSED, VSP_PENDING) == VSP_PENDING) {
        if (vsp_startup_slot) log_event("vshell_probes_startup_restore_failed");
        else vsp_start();
    }
    SetLastError(error); __asm__ volatile("fxrstor %0" :: "m"(fpu));
}
/* The replaced __startup import: every register and EFLAGS kept, the stack
 * as the caller left it, then a jump to the original import. */
void vsp_startup_entry(void);
__asm__(".text\n"
        ".globl _vsp_startup_entry\n"
        "_vsp_startup_entry:\n"
        "    pushal\n"
        "    pushfl\n"
        "    cld\n"
        "    call _vsp_arm\n"
        "    popfl\n"
        "    popal\n"
        "    jmp *_vsp_startup_original\n");

/* Step 1, from DLL_PROCESS_ATTACH. `self` is the proxy module. */
static void install_vshell_probes(HMODULE self) {
    WCHAR exe[MAX_PATH];
    DWORD n = GetModuleFileNameW(NULL, exe, MAX_PATH);
    WCHAR *name = n && n < MAX_PATH ? wcsrchr(exe, L'\\') : NULL;
    if (!name || _wcsicmp(name + 1, L"VSHELL.EXE")) return;
    n = GetEnvironmentVariableW(L"ES2_LIVE_COVERAGE_CONFIG", vsp_ini, MAX_PATH);
    if (!n || n >= MAX_PATH || !GetPrivateProfileIntW(L"vshell_probes", L"enabled", 0, vsp_ini)) return;
    n = GetModuleFileNameW(self, vsp_guard_ini, MAX_PATH);
    WCHAR *slash = n && n < MAX_PATH ? wcsrchr(vsp_guard_ini, L'\\') : NULL;
    if (slash && slash - vsp_guard_ini + 1 + wcslen(L"es2-oracle.ini") < MAX_PATH) wcscpy(slash + 1, L"es2-oracle.ini");
    else vsp_guard_ini[0] = 0;
    BYTE *image = (BYTE *)GetModuleHandleW(NULL);
    HMODULE rtl = GetModuleHandleW(L"cw3220.DLL");
    FARPROC expected = rtl ? GetProcAddress(rtl, "__startup") : NULL;
    DWORD *slot = es2_hook_image_valid(image, VSP_BASE, VSP_IMAGE_SIZE) ? vsp_import_slot(image, VSP_IMAGE_SIZE, "__startup") : NULL;
    /* No log_event here: the proxy's INI path is not known before the first
     * DirectDraw/MCI call, and the attach path reads no further file. */
    if (!slot || !expected || *slot != (DWORD)(uintptr_t)expected) { vsp_state = VSP_REFUSED; return; }
    vsp_startup_original = *slot; vsp_state = VSP_PENDING; vsp_startup_slot = slot;
    if (!vsp_swap(slot, vsp_startup_original, (DWORD)(uintptr_t)vsp_startup_entry)) {
        vsp_startup_slot = NULL; vsp_state = VSP_REFUSED;
    }
}
#endif
